VALUES (NULL, NULL, 15863, 'Crimson Skies', 'Crimson Skies', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22i8.jpg', NULL, 'The series is set within an alternate history of the 1930s invented by Weisman and McCoy. Within this divergent timeline, the United States has collapsed, and air travel has become the most popular mode of transportation in North America; as a result, air pirates thrive in the world of Crimson Skies. In describing the concept of Crimson Skies, Jordan Weisman stated he wanted to "take the idea of 16th century Caribbean piracy and translate into a 1930s American setting."', 'https://www.igdb.com/games/crimson-skies', '["Arcade", "PC (Microsoft Windows)"]', NULL, NULL, 0, 10.51, '2026-10-13 23:54:24', '2026-10-13 23:54:24')
