VALUES (17599, 'tt0073113', NULL, 'The Hindenburg', 'The Hindenburg', 'movie', 1975, 'https://image.tmdb.org/t/p/w500/wl7WA2xWUNUD6ChRPuDYJnHlu7u.jpg', 'https://image.tmdb.org/t/p/original/1daFkLpphDVzTyjBDw7rrHJajij.jpg', 'Colonel Franz Ritter, a former hero pilot now working for military intelligence, is assigned to the great Hindenburg airship as its chief of security. As he races against the clock to uncover a possible saboteur aboard the doomed zeppelin he finds that any of the passengers and crew could be the culprit.', NULL, NULL, 3.7554, 6.3, 0, 9.51, '2026-10-13 23:54:24', '2026-10-13 23:54:24')
