VALUES (66980, 'tt4378376', NULL, 'Babylon Berlin', 'Babylon Berlin', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/hr18RHPMQSA0zbCzAZN2asIOqy5.jpg', 'https://image.tmdb.org/t/p/original/7hezSIqkDjhP7MNGFN9vRkyWgO9.jpg', 'Beneath the decadence of 1929 Berlin, lies an underworld city of sin. Police investigator Gereon Rath has been transferred from Cologne to the epicenter of political and social changes in the Golden Twenties.', NULL, NULL, 34.8274, 7.743, 0, 11.01, '2026-10-13 23:54:24', '2026-10-13 23:54:24')
