VALUES (1462569, NULL, NULL, 'Wizard People, Dear Reader', 'Wizard People, Dear Reader', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/RbfgMd08Qm3ryoPH6hC907OWv8.jpg', NULL, 'Wizard People, Dear Reader, released in 2004, is an unauthorized alternative soundtrack to Harry Potter and the Philosopher''s Stone, written by Brad Neely, a comic book artist from Fort Smith, Arkansas.  Wizard People, Dear Reader is a narrative retelling of the lives of the characters of The Philosopher''s Stone and the world in which they live. Presented in the form of a thirty-five chapter audiobook, this soundtrack is intended to replace the film''s audio track.', NULL, NULL, 0.6409, 0.0, 0, 10.1, '2026-10-13 23:54:24', '2026-10-13 23:54:24')
