VALUES (2291, 'tt0099871', NULL, 'Jacob''s Ladder', 'Jacob''s Ladder', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/ufLcHIi1aXjjH8MediAMvnwDsVI.jpg', 'https://image.tmdb.org/t/p/original/oubk1SEFtg3Q8eOncFvGQVa6OoP.jpg', 'After returning home from the Vietnam War, veteran Jacob Singer struggles to maintain his sanity. Plagued by hallucinations and flashbacks, Singer rapidly falls apart as the world and people around him morph and twist into disturbing images. His girlfriend, Jezzie, and ex-wife, Sarah, try to help, but to little avail. Even Singer''s chiropractor friend, Louis, fails to reach him as he descends into madness.', NULL, NULL, 7.1628, 7.361, 0, 8.78217857142857241e+01, '2026-07-15 12:01:52', '2026-10-13 23:54:24')
