VALUES (9063, 'tt0087280', NULL, 'The Element of Crime', 'Forbrydelsens element', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/sfg5KUOdR4bfoPiDf63LVG7mlfw.jpg', 'https://image.tmdb.org/t/p/original/zpkSkHXm81jlFgXmTmmGQ4TuUzo.jpg', 'Fisher, an ex-detective, decides to take one final case when a mysterious serial killer claims the lives of several young girls. Fisher, unable to find the culprit, turns to Osbourne, a writer who was once respected for his contributions to the field of criminology. Fisher begins to use Osbourne''s technique, which involves empathizing with serial killers; however, as the detective becomes increasingly engrossed in this method, things take a disturbing turn.', NULL, NULL, 2.2307, 6.373, 0, 1.46866666666666656e+01, '2026-07-15 12:01:52', '2026-10-13 23:54:24')
