VALUES (24804, 'tt1190536', NULL, 'Black Dynamite', 'Black Dynamite', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/u3oWQDz0JggzzsVlsuHY7XVxp5Y.jpg', 'https://image.tmdb.org/t/p/original/gpcJuvH1tRWfdGv6ysWVRN3EZXL.jpg', 'This is the story of 1970s African-American action legend Black Dynamite. The Man killed his brother, pumped heroin into local orphanages, and flooded the ghetto with adulterated malt liquor. Black Dynamite was the one hero willing to fight The Man all the way from the blood-soaked city streets to the hallowed halls of the Honky House.', NULL, NULL, 3.0968, 7.081, 0, 13.098, '2026-07-15 12:01:52', '2026-10-13 23:54:24')
