VALUES (9470, 'tt0373074', NULL, 'Kung Fu Hustle', '功夫', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/exbyTbrvRUDKN2mcNEuVor4VFQW.jpg', 'https://image.tmdb.org/t/p/original/9XhZhoSnFJ3AjpfzdIiZVHLQIS4.jpg', 'It''s the 1940s, and the notorious Axe Gang terrorizes Shanghai. Small-time criminals Sing and Bone hope to join, but they only manage to make lots of very dangerous enemies. Fortunately for them, kung fu masters and hidden strength can be found in unlikely places. Now they just have to take on the entire Axe Gang.', NULL, NULL, 13.9875, 7.511, 0, 25.6535, '2026-07-15 12:01:52', '2026-10-13 23:54:24')
