VALUES (2907, 'tt0101272', NULL, 'The Addams Family', 'The Addams Family', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/qFf8anju5f2epI0my8RdwwIXFIP.jpg', 'https://image.tmdb.org/t/p/original/7OxGhxUYAdtuike29VMzEFxJx7y.jpg', 'When a man claiming to be long-lost Uncle Fester reappears after 25 years lost, the family plans a celebration to wake the dead. But the kids barely have time to warm up the electric chair before Morticia begins to suspect Fester is fraud when he can''t recall any of the details of Fester''s life.', NULL, NULL, 9.0602, 7.072, 0, 25.1645, '2026-07-15 12:01:52', '2026-10-13 23:54:24')
