VALUES (77, 'tt0209144', NULL, 'Memento', 'Memento', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/nzlv62aC0octS5AklAiWpXLX9Z0.jpg', 'https://image.tmdb.org/t/p/original/7Wev9JMo6R5XAfz2KDvXb7oPMmy.jpg', 'Leonard Shelby is tracking down the man who raped and murdered his wife. The difficulty of locating his wife''s killer, however, is compounded by the fact that he suffers from a rare, untreatable form of short-term memory loss. Although he can recall details of life before his accident, Leonard cannot remember what happened fifteen minutes ago, where he''s going, or why.', NULL, NULL, 23.8675, 8.175, 0, 4.23033333333333345e+01, '2026-07-20 04:02:06', '2026-10-13 23:54:24')
