VALUES (8779, 'tt0138919', NULL, 'The Vision of Escaflowne', '天空のエスカフローネ', 'tv', 1996, 'https://image.tmdb.org/t/p/w500/6uX0Q7Sn9JYWbHqQ5ZRJoJKcTmp.jpg', 'https://image.tmdb.org/t/p/original/ko65bRVvUAaOJ9Xw6vmXc6rHWxC.jpg', 'High school student Hitomi is transported from Earth to the magical world of Gaea, where she meets boy prince Van Fanel, and is caught up in his quest to unite the countries of Gaea against the ominous Zaibach empire. On the way, she discovers an hidden ability and strives to unravel layers of mystery surrounding Van, his past, and the giant machine known as Escaflowne.', NULL, NULL, 10.8922, 8.1, 0, 6.2625, '2026-07-29 20:51:09', '2026-10-13 23:54:24')
