VALUES (26320, 'tt1127896', NULL, 'Taking Woodstock', 'Taking Woodstock', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/wIdyAJCvIj3QUoNmmDdnhXpCMpp.jpg', 'https://image.tmdb.org/t/p/original/uhPAPblYLrp6UJXi0LdUHPTovkY.jpg', 'The story of Elliot Tiber and his family, who inadvertently played a pivotal role in making the famed Woodstock Music and Arts Festival into the happening that it was. When Elliot hears that a neighboring town has pulled the permit on a hippie music festival, he calls the producers thinking he could drum up some much-needed business for his parents'' run-down motel. Three weeks later, half a million people are on their way to his neighbor’s farm in White Lake, New York, and Elliot finds himself swept up in a generation-defining experience that would change his life–and American culture–forever.', NULL, NULL, 3.4516, 6.197, 0, 1.2322857142857142e+01, '2026-07-29 20:51:09', '2026-10-13 23:54:24')
