VALUES (9065, 'tt0101829', NULL, 'Europa', 'Europa', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/pyFtuYQReoSmhNs55kRJedA5wEJ.jpg', 'https://image.tmdb.org/t/p/original/9vOfO3CP8mqqq0oqCNl9R7M07xE.jpg', 'In 1945 Germany, following the end of World War II, Leopold Kessler, an American of German descent, is hired by his uncle as a sleeping car conductor on the Zentropa train line. Leopold''s wish is to be neutral to the ongoing purges of loyalists by Allied forces and do what he can to help a hurting country, but ultimately finds himself being used by both sides.', NULL, NULL, 2.49, 7.33, 0, 7.7625, '2026-08-04 03:20:13', '2026-10-13 23:54:24')
