VALUES (34164, 'tt0380113', NULL, 'Haibane Renmei', '灰羽連盟', 'tv', 2002, 'https://image.tmdb.org/t/p/w500/uSrIXnPIUkapk0JwMldDZTusl5O.jpg', 'https://image.tmdb.org/t/p/original/sC7DcOOWmQ2WNEVDjLY0t8rEwqS.jpg', 'A dream of falling from the sky...and then birth. Rakka is born from a large cocoon into the Old Home, greeted by a group of female beings with small wings on their backs and shining halos above their heads. Soon Rakka’s own wings grow, a halo is placed on her head and she is told that she must work in the nearby town of Grie. She soon realizes that the town and the entire world they live in are confined behind the Wall, a tall, impenetrable wall that none except the mysterious Toga are allowed to exit.', NULL, NULL, 10.3116, 7.7, 0, 9.34333333333333371e+00, '2026-08-18 01:44:45', '2026-10-13 23:54:24')
