VALUES (1159559, 'tt27047903', NULL, 'Scream 7', 'Scream 7', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/jjyuk0edLiW8vOSnlfwWCCLpbh5.jpg', 'https://image.tmdb.org/t/p/original/3eUyLEF5M0ky3h6KJsWiWzaakB8.jpg', 'When a new Ghostface killer emerges in the quiet town where Sidney Prescott has built a new life, her darkest fears are realized as her daughter becomes the next target. Determined to protect her family, Sidney must face the horrors of her past to put an end to the bloodshed once and for all.', NULL, NULL, 25.669, 6.236, 0, 9.03714285714285736e+00, '2026-08-20 01:43:50', '2026-10-13 23:54:24')
